SET NOCOUNT ON; SET XACT_ABORT ON;
BEGIN TRY BEGIN TRANSACTION;
DECLARE @ProjectID bigint=(SELECT ProjectID FROM dbo.TDADProject WHERE ProjectCode=N'LAOO_EVALUATION' AND IsActive=1); IF @ProjectID IS NULL THROW 53101,N'Active LAOO_EVALUATION project is required.',1;
DECLARE @G char(2)=N'47';
IF EXISTS(SELECT 1 FROM dbo.TDADMenuGroup WHERE MenuGroupCode=@G AND (AudienceType<>N'C' OR MenuGroupName<>N'ระบบประเมิน')) THROW 53102,N'Menu group conflicts.',1;
UPDATE dbo.TDADMenuGroup SET AudienceType=N'C',MenuGroupName=N'ระบบประเมิน',IconName=N'rate_review_outlined',SortOrder=470,IsExpandedDefault=0,IsActive=1,ShowPermissionPoint=0,OpenOption=0,UpdateDate=SYSUTCDATETIME() WHERE MenuGroupCode=@G;
IF NOT EXISTS(SELECT 1 FROM dbo.TDADMenuGroup WHERE MenuGroupCode=@G) INSERT dbo.TDADMenuGroup(AudienceType,MenuGroupCode,MenuGroupName,IconName,SortOrder,IsExpandedDefault,IsActive,CreateDate,ShowPermissionPoint,OpenOption) VALUES(N'C',@G,N'ระบบประเมิน',N'rate_review_outlined',470,0,1,SYSUTCDATETIME(),0,0);
DECLARE @M TABLE(MenuCode char(5) PRIMARY KEY,MenuName nvarchar(150),ScreenType int,RouteName nvarchar(150),RoutePath nvarchar(300),FeatureCode nvarchar(100),IconName nvarchar(100),SortOrder int);
INSERT @M VALUES (N'47001',N'ตั้งค่าระบบประเมิน',2,N'evaluationSettings',N'/company/evaluation-settings',N'EVALUATION_SETTINGS',N'settings_outlined',10),(N'47002',N'แบบประเมิน',1,N'evaluationTemplates',N'/company/evaluation-templates',N'EVALUATION_TEMPLATES',N'fact_check_outlined',20),(N'47003',N'รอบประเมิน',4,N'evaluationRounds',N'/company/evaluation-rounds',N'EVALUATION_ROUNDS',N'assignment_outlined',30),(N'47004',N'กล่องอนุมัติรอบประเมิน',3,N'evaluationApprovals',N'/company/evaluation-approvals',N'EVALUATION_APPROVALS',N'approval_outlined',40),(N'47005',N'งานประเมินของฉัน',3,N'myEvaluations',N'/company/my-evaluations',N'MY_EVALUATIONS',N'how_to_reg_outlined',50),(N'47006',N'ผลประเมิน',3,N'evaluationResults',N'/company/evaluation-results',N'EVALUATION_RESULTS',N'bar_chart_outlined',60),(N'47007',N'รายงานการประเมิน',3,N'evaluationReports',N'/company/evaluation-reports',N'EVALUATION_REPORTS',N'insights_outlined',70);
IF EXISTS(SELECT 1 FROM @M s JOIN dbo.TDADMainMenu t ON t.MenuCode=s.MenuCode WHERE t.MenuGroupCode<>@G OR t.ScreenType<>s.ScreenType OR ISNULL(t.RouteName,N'')<>s.RouteName OR ISNULL(t.RoutePath,N'')<>s.RoutePath) THROW 53103,N'MenuCode conflict.',1;
IF EXISTS(SELECT 1 FROM @M s JOIN dbo.TDADMainMenu t ON (t.RouteName=s.RouteName OR t.RoutePath=s.RoutePath) AND t.MenuCode<>s.MenuCode) THROW 53104,N'Route conflict.',1;
UPDATE t SET MenuGroupCode=@G,MenuName=s.MenuName,ScreenType=s.ScreenType,RouteName=s.RouteName,RoutePath=s.RoutePath,FeatureCode=s.FeatureCode,IconName=s.IconName,SortOrder=s.SortOrder,IsVisible=1,IsFavoriteAllowed=1,IsActive=1,ShowPermissionPoint=0,UpdateDate=SYSUTCDATETIME() FROM dbo.TDADMainMenu t JOIN @M s ON s.MenuCode=t.MenuCode;
INSERT dbo.TDADMainMenu(MenuCode,MenuGroupCode,MenuName,ScreenType,RouteName,RoutePath,FeatureCode,IconName,SortOrder,IsVisible,IsFavoriteAllowed,IsActive,CreateDate,ShowPermissionPoint) SELECT MenuCode,@G,MenuName,ScreenType,RouteName,RoutePath,FeatureCode,IconName,SortOrder,1,1,1,SYSUTCDATETIME(),0 FROM @M s WHERE NOT EXISTS(SELECT 1 FROM dbo.TDADMainMenu t WHERE t.MenuCode=s.MenuCode);
UPDATE dbo.TDADProjectMenuGroup SET SortOrder=1,IsActive=0,UpdateDate=SYSUTCDATETIME() WHERE ProjectID=@ProjectID AND MenuGroupCode=@G;
IF NOT EXISTS(SELECT 1 FROM dbo.TDADProjectMenuGroup WHERE ProjectID=@ProjectID AND MenuGroupCode=@G) INSERT dbo.TDADProjectMenuGroup(ProjectID,MenuGroupCode,SortOrder,IsActive,CreateDate) VALUES(@ProjectID,@G,1,0,SYSUTCDATETIME());
UPDATE pm SET MenuGroupCode=@G,SortOrder=s.SortOrder,IsActive=0,UpdateDate=SYSUTCDATETIME() FROM dbo.TDADProjectMenu pm JOIN @M s ON s.MenuCode=pm.MenuCode WHERE pm.ProjectID=@ProjectID;
INSERT dbo.TDADProjectMenu(ProjectID,MenuCode,MenuGroupCode,SortOrder,IsActive,CreateDate) SELECT @ProjectID,MenuCode,@G,SortOrder,0,SYSUTCDATETIME() FROM @M s WHERE NOT EXISTS(SELECT 1 FROM dbo.TDADProjectMenu pm WHERE pm.ProjectID=@ProjectID AND pm.MenuCode=s.MenuCode);
DECLARE @P TABLE(MenuCode char(5),ActionCode nvarchar(50),PRIMARY KEY(MenuCode,ActionCode)); INSERT @P VALUES (N'47001',N'VIEW'),(N'47001',N'EDIT'),(N'47002',N'VIEW'),(N'47002',N'CREATE'),(N'47002',N'EDIT'),(N'47002',N'DELETE'),(N'47003',N'VIEW'),(N'47003',N'CREATE'),(N'47003',N'EDIT'),(N'47003',N'DELETE'),(N'47003',N'SUBMIT'),(N'47003',N'CANCEL'),(N'47003',N'PUBLISH'),(N'47003',N'CLOSE'),(N'47004',N'VIEW'),(N'47004',N'APPROVE'),(N'47004',N'SELF_APPROVE'),(N'47005',N'VIEW'),(N'47005',N'SUBMIT'),(N'47006',N'VIEW'),(N'47007',N'VIEW');
UPDATE p SET ScreenNameTH=m.MenuName,ScreenNameEN=m.FeatureCode,ActionNameTH=p.ActionCode,ActionNameEN=p.ActionCode,IsActive=1,ModifiedDate=SYSUTCDATETIME() FROM dbo.TDADPermission p JOIN @P x ON x.MenuCode=p.ScreenCode AND x.ActionCode=p.ActionCode JOIN @M m ON m.MenuCode=x.MenuCode WHERE p.ProjectID=@ProjectID;
INSERT dbo.TDADPermission(ProjectID,ScreenCode,ScreenNameTH,ScreenNameEN,ActionCode,ActionNameTH,ActionNameEN,IsActive,CreatedDate) SELECT @ProjectID,x.MenuCode,m.MenuName,m.FeatureCode,x.ActionCode,x.ActionCode,x.ActionCode,1,SYSUTCDATETIME() FROM @P x JOIN @M m ON m.MenuCode=x.MenuCode WHERE NOT EXISTS(SELECT 1 FROM dbo.TDADPermission p WHERE p.ProjectID=@ProjectID AND p.ScreenCode=x.MenuCode AND p.ActionCode=x.ActionCode);
COMMIT TRANSACTION; END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK TRANSACTION; THROW; END CATCH;
GO
